mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.4) * p.xz;
  vec3 q = p - vec3(0.0, -0.4, 0.0);
  float m = max(abs(q.x), abs(q.z)) + q.y * 0.8 - 0.9;
  m = max(m, -q.y - 0.8);
  return m;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.3, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float scan = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    float slice = abs(fract(pos.y * 4.0 - time * 2.0) - 0.5);
    scan += (0.01 / (0.04 + abs(d))) * (0.5 + 0.5 * step(0.3, slice));
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = scan * vec3(0.1, 0.9, 1.0) * (0.8 + 0.3 * bass);
  ret = col;
}
